def drop_head(items, n):
    if n <= 0:
        return list(items)
    return items[n:]

reference.src/recursion.py:
def power(base, exp):
    if exp == 0:
        return 1
    if exp % 2 == 1:
        return base * power(base, exp - 1)
    half = power(base, exp // 2)
    return half * half

